// HTTP로 받은 파일 원본을 그대로 bytea 컬럼에 흘려 넣는다.
// content를 attribute로 올리지 않고 FlowFile InputStream을 JDBC에 바로 넘기므로
// 파일이 커도 NiFi 힙을 먹지 않는다(동영상 때문에 중요).
def TABLE = 'unstructured.video_files'

def ff = session.get()
if (!ff) return

def stmt = "INSERT INTO ${TABLE} (file_name, mime_type, byte_size, content, source_host) VALUES (?,?,?,?,?)".toString()
long len = ff.getSize()

def conn = CTL.tarandb.getConnection()
try {
    def ps = conn.prepareStatement(stmt)
    try {
        ff.read { stream ->
            ps.setString(1, ff.getAttribute('orig.filename') ?: 'unknown')
            ps.setString(2, ff.getAttribute('orig.mime'))
            ps.setLong(3, len)
            ps.setBinaryStream(4, stream, len)
            ps.setString(5, ff.getAttribute('restlistener.remote.source.host'))
            ps.executeUpdate()
        }
    } finally {
        ps.close()
    }
} finally {
    conn.close()
}

// ETL 로그 화면이 집계하는 카운터와 같은 이름으로 올려서 적재 건수에 잡히게 한다.
session.adjustCounter('INSERT updates performed', 1, false)
REL_SUCCESS << ff

